<script>
window.tibExportDesignLinks = function() {
  const images = Array.from(document.querySelectorAll('.tee-mockup-image img, .tee-printarea-wrapper--image img, #tee-gallery img'))
    .map(img => img.src)
    .filter(Boolean);
  const unique = [...new Set(images)];
  console.log('--- FOUND ' + unique.length + ' DESIGN / MOCKUP ASSETS ---');
  unique.forEach((src, idx) => console.log(`[${idx + 1}] ${src}`));
  return unique;
};
</script>
